window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[258]={"id":"258","numero":258,"titre":"Élévation de la créatininémie","objectifs":[{"id":"258-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l'interprétation d'un dosage de créatininémie","contenu":"<p>La <span class=\"kw-bio\">créatininémie</span> reflète la <span class=\"kw-def\">fonction rénale</span> mais reste un <span class=\"kw-alerte\">marqueur imparfait</span> : elle est <strong>inversement liée au <span class=\"kw-bio\">DFG</span></strong> et dépend aussi de la <span class=\"kw-def\">production musculaire de créatinine</span> (<span class=\"kw-clinique\">masse musculaire</span>, âge, sexe, alimentation).</p>\n      <ul>\n        <li>Forte <span class=\"kw-clinique\">masse musculaire</span> → <span class=\"kw-bio\">créatininémie</span> <span class=\"kw-clinique\">élevée sans insuffisance rénale</span>.</li>\n        <li>Sujet âgé <span class=\"kw-clinique\">dénutri</span> ou <span class=\"kw-clinique\">anorexie mentale</span> → <span class=\"kw-bio\">créatininémie</span> <span class=\"kw-clinique\">normale malgré une réelle insuffisance rénale</span>.</li>\n        <li>Toujours interpréter la <span class=\"kw-bio\">créatininémie</span> via le <span class=\"kw-bio\">DFG estimé</span>, qui la rend <strong>indépendante de la <span class=\"kw-clinique\">masse</span> musculaire</strong>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Âge</th><th>Valeurs normales de <span class=\"kw-bio\">créatininémie</span></th></tr></thead>\n        <tbody>\n          <tr><td>Naissance</td><td>≈ <span class=\"kw-chiffre\">80 µmol/L</span> (celle de la mère)</td></tr>\n          <tr><td>1ʳᵉ semaine de vie</td><td>chute à <span class=\"kw-chiffre\">20–30 µmol/L</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Enfant &lt; 5 ans</span></td><td>&lt; <span class=\"kw-chiffre\">35 µmol/L</span></td></tr>\n          <tr><td>Enfant <span class=\"kw-chiffre\">6–10 ans</span></td><td>&lt; <span class=\"kw-chiffre\">50 µmol/L</span></td></tr>\n          <tr><td>Adolescent (après puberté)</td><td>&lt; <span class=\"kw-chiffre\">90 µmol/L</span></td></tr>\n          <tr><td>Adulte</td><td><span class=\"kw-chiffre\">50–90 µmol/L</span> (femme) · <span class=\"kw-chiffre\">80–115 µmol/L</span> (homme)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"258-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les formules d'estimation du débit de filtration glomérulaire","contenu":"<p>Le <span class=\"kw-bio\">DFG estimé</span> (<span class=\"kw-bio\">DFGe</span>), exprimé en <span class=\"kw-chiffre\">mL/min/1,73 m²</span>, est le <strong>meilleur indicateur de la fonction rénale globale</strong>. <span class=\"kw-clinique\">Les</span> formules associent la <span class=\"kw-bio\">créatininémie</span> à des paramètres anthropométriques (<span class=\"kw-clinique\">âge</span>, <span class=\"kw-clinique\">sexe</span>, <span class=\"kw-clinique\">ethnie</span>).</p>\n      <table >\n        <thead><tr><th>Formule</th><th>Indication / dosage</th><th>Particularité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>CKD-EPI</strong></span></td>\n            <td>1ʳᵉ intention — <span class=\"kw-bio\">créatininémie</span> dosée par méthode <span class=\"kw-bio\">enzymatique</span></td>\n            <td>Supérieure à MDRD pour <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">valeurs basses</span> de <span class=\"kw-bio\">créatininémie</span> (<span class=\"kw-clinique\">hyperfiltration</span>, <span class=\"kw-clinique\">dénutrition</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>MDRD</strong></span></td>\n            <td><span class=\"kw-bio\">Créatininémie</span> dosée par méthode <span class=\"kw-bio\">colorimétrique</span></td>\n            <td>Estime <strong>directement le <span class=\"kw-bio\">DFG</span></strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Schwartz</strong></span></td>\n            <td>Spécifique de l'<span class=\"kw-clinique\">enfant &lt; 18 ans</span></td>\n            <td>Paramètres : <span class=\"kw-bio\">créatininémie</span> + <span class=\"kw-clinique\">taille</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Remarque.</strong> <span class=\"kw-def\">CKD-EPI</span>, <span class=\"kw-def\">MDRD</span> et <span class=\"kw-def\">Schwartz</span> estiment <strong>directement le <span class=\"kw-bio\">DFG</span></strong> et ne prennent <strong>pas en compte le poids</strong>, contrairement à <span class=\"kw-def\">Cockcroft-Gault</span>.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Attention.</strong> Ces formules ne sont <span class=\"kw-alerte\">pas valables en cas d'élévation aiguë</span> de la <span class=\"kw-bio\">créatininémie</span> (<span class=\"kw-etio\">IRA</span>) : elles supposent un <strong>état d'équilibre</strong> (hors éventuelle phase de plateau).\n      </div>","frequence":1},{"id":"258-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les formules d'estimation d'une clairance rénale de la créatinine","contenu":"<p>La <span class=\"kw-def\">clairance de la créatinine</span> est elle-même une <strong>estimation du <span class=\"kw-bio\">DFG</span></strong>. Elle peut être <strong>estimée</strong> (<span class=\"kw-def\">Cockcroft-Gault</span>) ou <strong>mesurée</strong> (recueil urinaire des <span class=\"kw-chiffre\">24 h</span>).</p>\n      <ul>\n        <li><span class=\"kw-def\"><strong>Cockcroft-Gault</strong></span> : estime la <span class=\"kw-bio\">clairance</span> ; paramètres <span class=\"kw-clinique\">âge</span>, <span class=\"kw-clinique\">sexe</span>, <span class=\"kw-clinique\">poids</span>, <span class=\"kw-bio\">créatininémie</span> ; résultat <strong>non indexé</strong> à la surface corporelle, en <span class=\"kw-chiffre\">mL/min</span>.</li>\n        <li>Formule <span class=\"kw-alerte\">imprécise</span> (surtout si altération de la fonction rénale), mais qui garde une place pour l'<strong>adaptation posologique</strong> de certains médicaments (usage pharmacocinétique historique).</li>\n        <li><span class=\"kw-bio\">Clairance urinaire mesurée</span> (<span class=\"kw-bio\">urines de 24 h</span>) : <strong>ne dépend pas de la <span class=\"kw-clinique\">masse</span> musculaire</strong> ; utile en cas de <span class=\"kw-clinique\">grossesse</span> ou d'<span class=\"kw-etio\">IRA</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Limites.</strong> La fiabilité du <span class=\"kw-bio\">recueil des urines de 24 h</span> est souvent prise en défaut, et la <span class=\"kw-bio\">clairance</span> <span class=\"kw-alerte\">surestime le DFG</span> (<span class=\"kw-bio\">créatinine</span> aussi <strong>sécrétée par le tubule</strong>).\n      </div>","frequence":0},{"id":"258-4","rang":"A","rubrique":"Prise en charge","titre":"Citer les circonstances au cours desquelles il convient de doser la créatininémie","contenu":"<p>Le dosage de la <span class=\"kw-bio\">créatininémie</span> (avec estimation du <span class=\"kw-bio\">DFG</span>) est indiqué dans toute situation à <span class=\"kw-alerte\">risque rénal</span> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span></strong> : <span class=\"kw-clinique\">âge &gt; 60 ans</span> ; <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">HTA</span> (traitée ou non), <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">maladie cardiovasculaire athéromateuse</span>, <span class=\"kw-etio\">insuffisance cardiaque</span>.</li>\n        <li><strong>Néphro-urologie</strong> : <span class=\"kw-clinique\">anomalie de l'appareil urinaire</span> (rein unique), <span class=\"kw-etio\">uropathie obstructive</span>, <span class=\"kw-etio\">infections urinaires</span> ou <span class=\"kw-etio\">lithiases récidivantes</span>.</li>\n        <li><strong>Antécédents</strong> : <span class=\"kw-clinique\">familiaux de maladie rénale</span> ; personnels d'<span class=\"kw-etio\">IRA</span> ou de néphropathie aiguë.</li>\n        <li><strong>Maladies systémiques / auto-immunes</strong> : <span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">vascularite</span>, <span class=\"kw-etio\">polyarthrite rhumatoïde</span>.</li>\n        <li><strong>Expositions</strong> : <span class=\"kw-etio\">toxiques professionnels</span> (plomb, cadmium, mercure) ; traitement <span class=\"kw-alerte\">néphrotoxique</span> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">PDC iodé</span>, <span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">radiothérapie</span>).</li>\n      </ul>","frequence":0},{"id":"258-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les arguments en faveur d'une insuffisance rénale chronique","contenu":"<p>Plusieurs arguments orientent vers une <span class=\"kw-etio\">insuffisance rénale chronique</span> (<span class=\"kw-etio\">IRC</span>) plutôt qu'aiguë :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Antécédent connu de maladie rénale</span> ; <span class=\"kw-bio\">créatininémie</span> déjà augmentée <strong>plusieurs mois ou années</strong> auparavant.</li>\n        <li><span class=\"kw-bio\">Marqueurs d'atteinte rénale &gt; 3 mois</span> : <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-bio\">leucocyturie</span>, <span class=\"kw-radio\">anomalies morphologiques</span> de l'appareil urinaire.</li>\n        <li><span class=\"kw-radio\">Reins de petite taille</span> à l'<span class=\"kw-imagerie\">échographie</span> (grand axe diminué).</li>\n        <li><span class=\"kw-bio\">Anémie</span> <span class=\"kw-clinique\">normocytaire arégénérative</span> (défaut d'<span class=\"kw-bio\">EPO</span>).</li>\n        <li><span class=\"kw-bio\">Hypocalcémie</span> par <span class=\"kw-clinique\">carence en vitamine D active</span> (<span class=\"kw-bio\">calcitriol</span> — défaut d'hydroxylation en 1α).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Exceptions (à connaître).</strong> <span class=\"kw-etio\">IRC</span> à <span class=\"kw-radio\">reins de taille normale ou augmentée</span> : <span class=\"kw-etio\">diabète</span> +++, <span class=\"kw-etio\">polykystose autosomique dominante</span>, <span class=\"kw-etio\">hydronéphrose bilatérale</span>, <span class=\"kw-etio\">amylose</span>, <span class=\"kw-etio\">néphropathie associée au VIH</span> (HIVAN), <span class=\"kw-etio\">myélome</span>. IRC <strong>sans anémie</strong> : <span class=\"kw-etio\">polykystose autosomique dominante</span>.\n      </div>","frequence":3},{"id":"258-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les arguments en faveur d'une insuffisance rénale aiguë","contenu":"<p>L'<span class=\"kw-etio\">insuffisance rénale aiguë</span> (<span class=\"kw-etio\">IRA</span>) se reconnaît à :</p>\n      <ul>\n        <li><strong>Élévation rapide</strong> de la <span class=\"kw-bio\">créatininémie</span>, avec une <span class=\"kw-bio\">valeur antérieure normale</span>.</li>\n        <li><span class=\"kw-clinique\">Contexte exposant à une IRA</span> : <span class=\"kw-etio\">état de choc</span>, <span class=\"kw-etio\">réanimation</span>, certains <span class=\"kw-ttt\">médicaments</span>.</li>\n        <li><strong>Absence de marqueurs anciens</strong> (<span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-bio\">leucocyturie</span>).</li>\n        <li><span class=\"kw-radio\">Taille des reins normale</span> (grand axe <span class=\"kw-chiffre\">&gt; 10 cm</span>) à l'<span class=\"kw-imagerie\">échographie</span>.</li>\n        <li><strong>Absence d'<span class=\"kw-bio\">anémie</span></strong> et <strong>absence d'<span class=\"kw-bio\">hypocalcémie</span></strong>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une <span class=\"kw-etio\">IRA</span> peut compliquer une <span class=\"kw-etio\">IRC</span> (« <span class=\"kw-alerte\">IRA sur IRC</span> », après <span class=\"kw-ttt\">PDC iodé</span>, <span class=\"kw-ttt\">AINS</span>, néphrotoxique). En cas de doute persistant, <strong>considérer l'<span class=\"kw-ci\">insuffisance rénale</span> comme aiguë</strong>.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Associations utiles.</strong> <span class=\"kw-clinique\">IRA + anémie</span> → <span class=\"kw-etio\">hémolyse aiguë</span>, <span class=\"kw-etio\">choc hémorragique</span>, <span class=\"kw-etio\">syndrome inflammatoire</span> (<span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-clinique\">vascularite</span>). <span class=\"kw-clinique\">IRA + hypocalcémie</span> → <span class=\"kw-etio\">rhabdomyolyse</span>, <span class=\"kw-etio\">syndrome de lyse tumorale</span>.\n      </div>","frequence":0},{"id":"258-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les arguments en faveur de la nature obstructive d'une élévation de la créatininémie","contenu":"<p>Évoquer une <span class=\"kw-def\">origine obstructive (post-rénale)</span> devant :</p>\n      <ul>\n        <li><strong>Anamnèse</strong> : antécédents de <span class=\"kw-etio\">lithiase</span>, de <span class=\"kw-etio\">pathologie prostatique</span> (HBP, cancer), de <span class=\"kw-etio\">tumeur pelvienne</span> (vessie, col utérin, ovaire, rectum), de <span class=\"kw-etio\">fibrose rétropéritonéale</span> ou de <span class=\"kw-ttt\">radiothérapie</span>.</li>\n        <li><strong>Clinique</strong> : <span class=\"kw-clinique\">douleur lombaire</span> uni- ou bilatérale, <span class=\"kw-clinique\">colique néphrétique</span> ; <span class=\"kw-clinique\">hématurie macroscopique avec caillots</span> ; <span class=\"kw-clinique\">dysurie</span>, <span class=\"kw-clinique\">mictions par regorgement</span>, <span class=\"kw-clinique\">globe vésical</span>.</li>\n        <li><strong>Toucher pelvien</strong> : <span class=\"kw-clinique\">blindage pelvien</span> (<span class=\"kw-alerte\">TV</span>/TR), <span class=\"kw-clinique\">HBP</span>, <span class=\"kw-clinique\">masse</span>.</li>\n        <li><strong>Diurèse</strong> : <span class=\"kw-clinique\">anurie inconstante</span> (l'obstacle peut être incomplet).</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Principales causes.</strong> <em>Obstacle sous-vésical</em> : <span class=\"kw-etio\">pathologie prostatique</span> (HBP, cancer, <span class=\"kw-clinique\">prostatite</span>), <span class=\"kw-etio\">sténose urétrale</span>, <span class=\"kw-etio\">caillotage ou tumeur de vessie</span>, <span class=\"kw-etio\">prolapsus</span>. <em>Obstacle sus-vésical</em> (bilatéral ou sur rein unique) : <span class=\"kw-etio\">lithiases</span>, <span class=\"kw-etio\">compressions tumorales</span> (cancers pelviens, <span class=\"kw-clinique\">adénopathies</span>), <span class=\"kw-etio\">fibrose rétropéritonéale</span>, <span class=\"kw-etio\">ligature urétérale iatrogène</span>.\n      </div>","frequence":0},{"id":"258-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser devant une élévation de la créatininémie présumée d'origine obstructive","contenu":"<p>Devant une élévation présumée d'<span class=\"kw-def\">origine obstructive</span> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Échographie des voies urinaires</span> = examen de <strong>1ʳᵉ intention</strong> : une <span class=\"kw-radio\">dilatation des cavités pyélocalicielles</span> <strong>affirme le diagnostic</strong> ; précise le <span class=\"kw-radio\">niveau de l'obstacle</span> et la <span class=\"kw-radio\">taille des reins</span>.</li>\n        <li>Une <span class=\"kw-imagerie\">échographie normale</span> (ou simple <span class=\"kw-radio\">hypotonie</span>) <span class=\"kw-alerte\">n'exclut pas</span> une origine obstructive (début précoce, fibrose engainante).</li>\n        <li><span class=\"kw-imagerie\">TDM abdomino-pelvienne sans injection</span> (ou <span class=\"kw-imagerie\">uro-IRM</span>) pour préciser la cause — <span class=\"kw-etio\">lithiase</span>, <span class=\"kw-etio\">infiltration tumorale/fibreuse</span>.</li>\n        <li><span class=\"kw-ci\">Produit de contraste iodé à proscrire</span> dans ce contexte (UIV / uro-<span class=\"kw-imagerie\">TDM</span> injectés <span class=\"kw-ci\">contre-indiqués</span>).</li>\n      </ul>","frequence":0},{"id":"258-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les arguments en faveur de la nature fonctionnelle d'une élévation de la créatininémie","contenu":"<p>Évoquer une <span class=\"kw-def\">origine fonctionnelle (pré-rénale)</span>, c'est-à-dire un <strong>rein sain hypoperfusé</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Hypovolémie vraie</span> : <span class=\"kw-etio\">hémorragie</span>, <span class=\"kw-etio\">déshydratation extracellulaire</span> (pertes digestives, rénales, cutanées, 3ᵉ secteur).</li>\n        <li><span class=\"kw-def\">Hypovolémie efficace</span> : <span class=\"kw-etio\">insuffisance cardiaque</span>, <span class=\"kw-etio\">insuffisance hépatique</span> (syndrome hépatorénal), <span class=\"kw-etio\">sepsis</span>.</li>\n        <li><span class=\"kw-def\">IRA hémodynamique médicamenteuse</span> : <span class=\"kw-ttt\">AINS</span> (vasoconstriction de l'<span class=\"kw-clinique\">artériole afférente</span>), <span class=\"kw-ttt\">IEC/ARA2</span> (vasodilatation de l'<span class=\"kw-clinique\">artériole efférente</span>), <span class=\"kw-ttt\">anticalcineurines</span>, <span class=\"kw-ttt\">diurétiques</span>.</li>\n        <li><strong>Clinique / biologie</strong> : <span class=\"kw-clinique\">oligurie</span> ; élévation de l'<span class=\"kw-bio\">urée</span> &gt; élévation de la <span class=\"kw-bio\">créatinine</span> ; urines <span class=\"kw-bio\">pauvres en Na⁺</span>, <span class=\"kw-bio\">riches en K⁺</span>, <span class=\"kw-bio\">concentrées</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Principales causes.</strong> <span class=\"kw-etio\">Déshydratation</span> (<span class=\"kw-ttt\">diurétiques</span>, pertes digestives/cutanées), <span class=\"kw-etio\">états de choc</span> et bas débit cardiaque, <span class=\"kw-etio\">syndrome hépatorénal</span>, <span class=\"kw-etio\">hypovolémie efficace</span> (cirrhose, <span class=\"kw-clinique\">syndrome néphrotique</span>), <span class=\"kw-ttt\">médicaments</span> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC</span>, <span class=\"kw-ttt\">ARA2</span>, anticalcineurines).\n      </div>","frequence":0},{"id":"258-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser devant une élévation de la créatininémie présumée d'origine fonctionnelle","contenu":"<p>Devant une élévation présumée d'<span class=\"kw-def\">origine fonctionnelle</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">indices urinaires</span> traduisent un <strong>rein « avide de sodium »</strong>. Ils distinguent le mécanisme <span class=\"kw-def\">fonctionnel</span> de la <span class=\"kw-etio\">NTA</span> (organique) :</p>\n      <table >\n        <thead><tr><th>Indice</th><th>Fonctionnelle (pré-rénale)</th><th>NTA (organique)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Na⁺ urinaire</span></td><td>&lt; <span class=\"kw-chiffre\">20 mmol/L</span></td><td>&gt; <span class=\"kw-chiffre\">40 mmol/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\">FeNa</span></td><td>&lt; <span class=\"kw-chiffre\">1 %</span></td><td>&gt; <span class=\"kw-chiffre\">1–2 %</span></td></tr>\n          <tr><td><span class=\"kw-bio\">FeUrée</span> (si <span class=\"kw-ttt\">diurétiques</span>)</td><td>&lt; <span class=\"kw-chiffre\">35 %</span></td><td>&gt; <span class=\"kw-chiffre\">35–40 %</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Urée/créatinine plasm.</span> (µmol/L)</td><td>&gt; <span class=\"kw-chiffre\">100</span></td><td>&lt; <span class=\"kw-chiffre\">50</span></td></tr>\n          <tr><td><span class=\"kw-bio\">U/P urée</span></td><td>&gt; <span class=\"kw-chiffre\">10</span></td><td>&lt; <span class=\"kw-chiffre\">10</span></td></tr>\n          <tr><td><span class=\"kw-bio\">U/P créatinine</span></td><td>&gt; <span class=\"kw-chiffre\">30</span></td><td>&lt; <span class=\"kw-chiffre\">30</span></td></tr>\n          <tr><td><span class=\"kw-bio\">U/P osmoles</span></td><td>&gt; <span class=\"kw-chiffre\">2</span></td><td>&lt; <span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Na⁺/K⁺ urinaire</span></td><td>&lt; <span class=\"kw-chiffre\">1</span></td><td>&gt; <span class=\"kw-chiffre\">1</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège <span class=\"kw-ttt\">diurétiques</span>.</strong> En cas de <span class=\"kw-clinique\">pertes rénales de sodium</span> (<span class=\"kw-ttt\">diurétiques</span>, hypoaldostéronisme, diurèse osmotique), la <span class=\"kw-bio\">natriurèse</span> et la <span class=\"kw-bio\">FeNa</span> sont prises en défaut : le meilleur indicateur d'une IRA fonctionnelle est alors la <span class=\"kw-chiffre\">FeUrée &lt; 35 %</span>. <span class=\"kw-bio\">Sédiment urinaire normal</span>, pas de <span class=\"kw-bio\">protéinurie</span> significative.\n      </div>","frequence":0},{"id":"258-11","rang":"A","rubrique":"Étiologies","titre":"Connaître les arguments en faveur de la nature parenchymateuse d'une élévation","contenu":"<p>Évoquer une <span class=\"kw-def\">origine parenchymateuse (organique)</span> devant l'<strong>absence d'obstacle</strong> et l'<strong>absence de réponse au remplissage</strong>, puis caractériser le <strong>siège de l'atteinte</strong> :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Arguments orientant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>NTA</strong></span> (tubulaire)</td><td><span class=\"kw-clinique\">IRA « nue »</span> : <span class=\"kw-bio\">protéinurie tubulaire &lt; 1 g/j</span>, <strong>pas</strong> d'<span class=\"kw-bio\">hématurie</span>/<span class=\"kw-etio\">HTA</span>/<span class=\"kw-clinique\">œdèmes</span> ; contexte <span class=\"kw-etio\">ischémique</span> ou <span class=\"kw-etio\">toxique</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>NIA</strong></span> (interstitielle)</td><td><span class=\"kw-bio\">Leucocyturie</span>, <span class=\"kw-bio\">éosinophilurie</span> (immuno-<span class=\"kw-etio\">allergique</span>), contexte <span class=\"kw-etio\">médicamenteux</span> ou <span class=\"kw-etio\">infectieux</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Glomérulaire</strong></span></td><td><span class=\"kw-bio\">Protéinurie &gt; 1 g/j</span> (<span class=\"kw-bio\">albumine ≥ 60 %</span>), <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span> ± signes extra-rénaux (<span class=\"kw-etio\">vascularite</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Vasculaire</strong></span></td><td><span class=\"kw-clinique\">HTA au 1ᵉʳ plan</span>, contexte de <span class=\"kw-etio\">MAT</span>/<span class=\"kw-etio\">embols de cholestérol</span>/<span class=\"kw-etio\">infarctus rénal</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Principales causes.</strong> <span class=\"kw-etio\">NTA</span> +++ (<span class=\"kw-etio\">ischémique</span> : <span class=\"kw-alerte\">choc</span> ; <span class=\"kw-etio\">toxique</span> : <span class=\"kw-ttt\">aminosides</span>, <span class=\"kw-ttt\">vancomycine</span>, <span class=\"kw-ttt\">PDC iodé</span>, <span class=\"kw-ttt\">cisplatine</span>, rhabdomyolyse, lyse <span class=\"kw-etio\">tumorale</span>, myélome) · <span class=\"kw-etio\">NIA</span> (médicamenteuse, infectieuse) · <span class=\"kw-etio\">glomérulonéphrites aiguës et vascularites</span> (GNRP, post-infectieuse, <span class=\"kw-clinique\">lupus</span>) · <span class=\"kw-etio\">néphropathies vasculaires</span> (néphroangiosclérose maligne, SHU/MAT, embols de <span class=\"kw-bio\">cholestérol</span>).\n      </div>","frequence":0},{"id":"258-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser devant une élévation de la créatininémie présumée d'origine parenchymateuse","contenu":"<p>Devant une élévation présumée d'<span class=\"kw-def\">origine parenchymateuse</span> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Bandelette urinaire</span> : <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-bio\">leucocyturie</span>.</li>\n        <li><span class=\"kw-bio\">Protéinurie des 24 h</span> (ou <span class=\"kw-bio\">ratio protéinurie/créatininurie</span>) et son <strong>profil</strong> (<span class=\"kw-bio\">glomérulaire ≥ 60 % d'albumine</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-bio\">tubulaire &lt; 1 g/j</span>).</li>\n        <li><span class=\"kw-bio\">Sédiment urinaire</span> : <span class=\"kw-bio\">cylindres</span>, <span class=\"kw-bio\">hématies déformées</span>, <span class=\"kw-bio\">leucocytes</span>.</li>\n        <li>Indices urinaires de type organique : <span class=\"kw-chiffre\">Na⁺ urinaire &gt; 40 mmol/L</span>, <span class=\"kw-chiffre\">FeNa &gt; 1–2 %</span>.</li>\n        <li><strong>Immunologie</strong> si suspicion de GN/<span class=\"kw-clinique\">vascularite</span> : <span class=\"kw-bio\">ANCA</span>, <span class=\"kw-bio\">AAN</span>, <span class=\"kw-bio\">anti-MBG</span>, <span class=\"kw-bio\">complément (C3/C4)</span>, <span class=\"kw-bio\">électrophorèse des protéines</span>.</li>\n        <li><span class=\"kw-alerte\">Ponction-biopsie rénale (PBR)</span> : devant une atteinte <span class=\"kw-etio\">non-NTA</span> (glomérulaire/vasculaire/interstitielle), une NTA de circonstances atypiques, ou une <span class=\"kw-clinique\">IRA ne récupérant pas à 3–4 semaines</span>.</li>\n      </ul>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p>Devant toute élévation, la 1ʳᵉ question est le caractère <span class=\"kw-def\">aigu</span> ou <span class=\"kw-def\">chronique</span> : l'<span class=\"kw-def\">IRA</span> est l'<span class=\"kw-alerte\">urgence</span> car potentiellement <strong>réversible</strong>.</p><p><strong>En faveur d'une <span class=\"kw-def\">IRA</span> <span class=\"q\">— <span class=\"kw-alerte\">urgence</span></span></strong></p><p>Contexte exposant : <span class=\"kw-etio\">état de choc</span>, <span class=\"kw-etio\">réanimation</span>, <span class=\"kw-ttt\">médicaments néphrotoxiques</span></p><ul><li>Élévation <strong>rapide</strong> de la <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">valeur antérieure normale</span></li><li><span class=\"kw-imagerie\">Reins de taille normale</span> (grand axe <span class=\"kw-chiffre\">&gt; 10 cm</span>)</li><li>Absence d'<span class=\"kw-bio\">anémie</span> et d'<span class=\"kw-bio\">hypocalcémie</span></li></ul><p><strong>En faveur d'une <span class=\"kw-def\">IRC</span></strong></p><ul><li><span class=\"kw-clinique\">Antécédent de maladie rénale</span> · <span class=\"kw-bio\">créatininémie</span> déjà élevée des mois/années auparavant</li><li><span class=\"kw-imagerie\">Reins de petite taille</span> · <span class=\"kw-bio\">anémie normocytaire arégénérative</span> · <span class=\"kw-bio\">hypocalcémie</span></li></ul><p><strong><span class=\"kw-alerte\">IRA sur IRC</span> <span class=\"q\">— piège</span></strong></p><p>Doute persistant → <span class=\"kw-alerte\">considérer l'insuffisance rénale comme aiguë</span></p><ul><li>Une <span class=\"kw-clinique\">IRA</span> peut compliquer une <span class=\"kw-clinique\">IRC</span> après <span class=\"kw-ttt\">PDC iodé</span>, <span class=\"kw-ttt\">AINS</span> ou néphrotoxique</li></ul>","principes":"<p>Raisonner par <strong>mécanisme</strong>, dans l'ordre : <span class=\"kw-def\">obstructif</span> (post-rénal) → <span class=\"kw-def\">fonctionnel</span> (pré-rénal) → <span class=\"kw-def\">parenchymateux</span> (organique, par défaut). À chaque mécanisme, ses arguments et son examen d'orientation.</p><p><strong><span class=\"kw-def\">Obstructif</span> (post-rénal) <span class=\"q\">— à écarter en 1ᵉʳ</span></strong></p><p><span class=\"kw-imagerie\">Échographie des voies urinaires</span> (1ʳᵉ intention) : <span class=\"kw-imagerie\">dilatation des cavités pyélocalicielles</span> affirme le diagnostic · <span class=\"kw-ci\">PDC iodé à proscrire</span></p><ul><li>Anamnèse : <span class=\"kw-etio\">lithiase</span>, <span class=\"kw-etio\">pathologie prostatique</span>, <span class=\"kw-etio\">tumeur pelvienne</span>, <span class=\"kw-etio\">fibrose rétropéritonéale</span></li><li>Clinique : <span class=\"kw-clinique\">colique néphrétique</span>, <span class=\"kw-clinique\">globe vésical</span>, <span class=\"kw-clinique\">anurie</span> (inconstante), <span class=\"kw-clinique\">blindage pelvien</span> au TR/<span class=\"kw-alerte\">TV</span></li></ul><p><strong><span class=\"kw-def\">Fonctionnel</span> (pré-rénal) <span class=\"q\">— rein sain hypoperfusé</span></strong></p><p><span class=\"kw-bio\">Indices urinaires</span> : <span class=\"kw-chiffre\">Na⁺ &lt; 20 mmol/L</span>, <span class=\"kw-chiffre\">FeNa &lt; 1 %</span> (<span class=\"kw-chiffre\">FeUrée &lt; 35 %</span> si <span class=\"kw-ttt\">diurétiques</span>)</p><ul><li><span class=\"kw-def\">Hypovolémie vraie</span> (<span class=\"kw-etio\">hémorragie</span>, <span class=\"kw-etio\">déshydratation extracellulaire</span>) ou <span class=\"kw-def\">efficace</span> (<span class=\"kw-etio\">insuffisance cardiaque</span>, <span class=\"kw-etio\">syndrome hépatorénal</span>, <span class=\"kw-etio\">sepsis</span>)</li><li>Médicaments : <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC/ARA2</span>, <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">anticalcineurines</span></li><li><span class=\"kw-clinique\">Oligurie</span> · élévation de l'<span class=\"kw-bio\">urée</span> &gt; celle de la <span class=\"kw-bio\">créatinine</span> · urines <span class=\"kw-bio\">pauvres en Na⁺</span>, <span class=\"kw-bio\">concentrées</span></li></ul><p><strong><span class=\"kw-def\">Parenchymateux</span> (organique) <span class=\"q\">— par défaut</span></strong></p><p><span class=\"kw-bio\">Bandelette urinaire</span>, <span class=\"kw-bio\">protéinurie des 24 h</span>, <span class=\"kw-bio\">sédiment urinaire</span>, <span class=\"kw-bio\">immunologie</span> (<span class=\"kw-bio\">ANCA</span>, <span class=\"kw-bio\">AAN</span>, <span class=\"kw-bio\">complément</span>) ± <span class=\"kw-alerte\">PBR</span></p><ul><li>Évoqué devant l'<strong>absence d'obstacle</strong> et l'<strong>absence de réponse au remplissage</strong></li><li>Caractériser le siège : <span class=\"kw-etio\">NTA</span> (IRA « nue ») · <span class=\"kw-etio\">NIA</span> (<span class=\"kw-bio\">leucocyturie</span>, <span class=\"kw-bio\">éosinophilurie</span>) · <span class=\"kw-etio\">glomérulaire</span> (<span class=\"kw-bio\">protéinurie &gt; 1 g/j</span>, <span class=\"kw-clinique\">hématurie</span>, <span class=\"kw-clinique\">HTA</span>) · <span class=\"kw-etio\">vasculaire</span></li></ul>","suivi":"<p><strong>Affirmer la chronicité :</strong> <span class=\"kw-bio\">marqueurs d'atteinte rénale</span> (<span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-bio\">leucocyturie</span>, <span class=\"kw-imagerie\">anomalies morphologiques</span>) persistant <span class=\"kw-chiffre\">&gt; 3 mois</span>.<br><strong><span class=\"kw-bio\">DFG</span> estimé :</strong> <span class=\"kw-def\">suivi</span> de la fonction rénale par <span class=\"kw-bio\">CKD-EPI</span> — <span class=\"kw-alerte\">non valable en phase aiguë</span> (suppose un état d'équilibre), à réévaluer après stabilisation.<br><strong><span class=\"kw-ttt\">Biopsie</span> rénale :</strong> <span class=\"kw-alerte\">PBR</span> devant une atteinte <span class=\"kw-etio\">non-NTA</span> (glomérulaire / vasculaire / interstitielle), une NTA atypique, ou une <span class=\"kw-clinique\">IRA ne récupérant pas</span> à <span class=\"kw-chiffre\">3–4 semaines</span>.</p>"},"cards":[]};